mapper.select:
SELECT
COUNT(*) AS orderCount,
IFNULL(SUM(CASE WHEN `status` = 1 THEN `pay_amount` ELSE 0 END), 0) AS revenue,
IFNULL(SUM(CASE WHEN `divide_status` = 0 THEN `pay_amount` ELSE 0 END), 0) AS pendingAmount
FROM `shop_order`
WHERE `shop_id` = #{param.searchField4}

    AND `create_time` BETWEEN #{param.startTime} AND #{param.endTime}


    AND nick_name LIKE CONCAT('%',#{param.searchStrField1},'%')


    AND order_no LIKE CONCAT('%',#{param.searchStrField2},'%')


    AND  status = #{param.searchType}

select id, order_no, equipment_id, shop_id, shop_name, business_circle_id, business_circle_name, total_amount, deduct_coin, deduct_amount, pay_amount, order_time, user_id, phone, nick_name, status, refund_reason, refund_time, remark, divide_status, divide_amount, divide_time from `shop_order`
AND shop_id = #{param.searchId}
AND nick_name LIKE CONCAT('%',#{param.searchStrField1},'%')
AND order_no LIKE CONCAT('%',#{param.searchStrField2},'%')
AND status = #{param.searchType}
order by order_time desc

SELECT *
FROM `shop_order`

    AND user_id = #{param.searchField1}

        AND `order_type` IN

            #{item}



        AND `status` IN

            #{item}


    AND `status` = #{param.searchIntStatus}
    AND `divide_status` = #{param.searchField2}
    AND `shop_id` = #{param.searchField3}

        AND `order_no` LIKE CONCAT('%', #{param.searchStrField1}, '%')


        AND (phone LIKE CONCAT('%',#{param.keyword},'%') OR nick_name LIKE CONCAT('%',#{param.keyword},'%'))


        AND `order_time` >= #{param.limitTime}


        AND `create_time` BETWEEN #{param.startTime} AND #{param.endTime}


ORDER BY `id` desc

