UPDATE `shop_order` SET
status = #{data.status}, refund_reason = #{data.refundReason}, divide_status = #{data.divideStatus}, divide_amount = #{data.divideAmount}, divide_time = #{data.divideTime}, refund_time = #{data.refundTime}, update_time = now()
WHERE id = #{data.id}
